	private void button2_Click(object sender, EventArgs e)
	{
		if (!string.IsNullOrEmpty(textBox1.Text))
		{
			int num = listBox1.FindString(textBox1.Text);
			if (num != -1)
			{
				listBox1.SetSelected(num, value: true);
				return;
			}
			string text = "The search string did not match any items in the ListBox";
			MessageBox.Show(text);
		}
	}

	private void cboBankList_SelectedIndexChanged(object sender, EventArgs e)
	{
		if (cboBankList.SelectedIndex < 0)
		{
			Form owner = new Form
			{
				TopMost = true
			};
			string text = "Select Bank";
			string caption = "Error";
			MessageBox.Show(owner, text, caption, MessageBoxButtons.OK, MessageBoxIcon.Hand);
		}
		else
		{
			string key = cboBankList.SelectedItem.ToString();
			bnk_id = dictionary_bnk[key];
		}
	}

